"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import type { Project } from "@/lib/projects";

const AUTOPLAY_MS = 9000;

export default function HeroSlider({ projects }: { projects: Project[] }) {
  const slides = useMemo(
    () =>
      projects.filter(
        (project) =>
          project.featured &&
          Boolean(project.hero_image || project.cover_image)
      ),
    [projects]
  );

  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    if (slides.length <= 1 || paused) return;

    const timer = window.setInterval(() => {
      setIndex((current) => (current + 1) % slides.length);
    }, AUTOPLAY_MS);

    return () => window.clearInterval(timer);
  }, [slides.length, paused]);

  useEffect(() => {
    if (index >= slides.length) setIndex(0);
  }, [index, slides.length]);

  if (!slides.length) {
    return (
      <section className="hero">
        <div className="hero-media" />
      </section>
    );
  }

  const current = slides[index];

  const previous = () =>
    setIndex((value) => (value === 0 ? slides.length - 1 : value - 1));

  const next = () =>
    setIndex((value) => (value === slides.length - 1 ? 0 : value + 1));

  return (
    <section
      className="hero"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
    >
      <div className="hero-slides">
        {slides.map((project, slideIndex) => {
          const src = project.hero_image ?? project.cover_image ?? "";

          return (
            <div
              key={project.id}
              className={`hero-slide ${slideIndex === index ? "is-active" : ""}`}
              aria-hidden={slideIndex !== index}
            >
              <img src={src} alt={project.title} />
            </div>
          );
        })}
      </div>

      <Link
        key={current.id}
        href={`/proyectos/${current.slug}`}
        className="hero-label hero-label-fade"
      >
        {current.title}
      </Link>

      {slides.length > 1 && (
        <>
          <button
            className="hero-arrow left"
            type="button"
            aria-label="Proyecto anterior"
            onClick={previous}
          >
            ‹
          </button>
          <button
            className="hero-arrow right"
            type="button"
            aria-label="Proyecto siguiente"
            onClick={next}
          >
            ›
          </button>
        </>
      )}
    </section>
  );
}
